options.content:
{{#if (eq isAllowed "1")}}
{{#if coverage}}
<div class="h360-cov">Coverage: {{coverage}}</div>
{{/if}}
{{else}}
<div class="ovq-warn"><span>⚠️</span><span><strong>Access Denied:</strong> Ask admin to add to one of these teams: {{{requiredGroups}}}</span></div>
{{/if}}

options.afterRender:
// Enter stock form (story 3.5). One number per protocol drug and strength for one facility
// and month. Saves to h360-api, which takes identity from the Grafana session.
const root = context.element.querySelector('.dse');
if (!root) { return; }

const series = (context.panelData && context.panelData.series) || [];
const frame = series.find((s) => s.refId === 'A');
const all = (() => {
  if (!frame) { return []; }
  const cols = frame.fields.map((x) => [x.name, Array.from(x.values)]);
  const n = cols.length ? cols[0][1].length : 0;
  return Array.from({ length: n }, (_, i) => Object.fromEntries(cols.map(([k, v]) => [k, v[i]])));
})();
const flags = all[0] || {};
const rows = all.filter((r) => r.drug_code != null);

const esc = (v) => String(v == null ? '' : v).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const warn = (html) => '<div class="dse-warn"><span>⚠️</span><span>' + html + '</span></div>';

if (Number(flags.isAllowed) !== 1) {
  root.innerHTML = warn('<strong>Access Denied:</strong> Ask admin to add to one of these teams: ' + (flags.requiredGroups || ''));
  return;
}
if (Number(flags.isFacility) !== 1 || !rows.length) {
  root.innerHTML = '<div class="dse-note">Pick one facility to enter stock.</div>';
  return;
}

const MAX = 1000000;
const orgId = Number(flags.org_unit_id);
const months = [...new Map(rows.map((r) => [r.month, r.month_label])).entries()];
// Kept across the refresh that follows a save, so the form reopens on the saved month with its note.
const memo = (window.__h360StockEntry = window.__h360StockEntry || {});
const recent = memo.org === orgId && Date.now() - (memo.at || 0) < 8000 ? memo : null;
let month = (recent && recent.month) || flags.this_month;
if (!months.some(([m]) => m === month)) { month = months[0][0]; }

const fmt = (n) => Number(n).toLocaleString('en-US');
const ofMonth = (m) => rows.filter((r) => r.month === m);

const render = () => {
  const list = ofMonth(month);
  const last = list.filter((r) => r.saved_on).sort((a, b) => String(b.saved_on).localeCompare(String(a.saved_on)))[0];
  root.innerHTML = '<h2 class="dse-title">Enter stock</h2>'
    + '<div class="dse-head">' + esc(flags.place) + '. Count tablets in stock. Leave blank if not counted. Enter 0 if none.</div>'
    + '<form class="dse-form" novalidate>'
    + '<label class="dse-field dse-month-field"><span>Month</span><select class="dse-month">'
    + months.map(([m, label]) => '<option value="' + esc(m) + '"' + (m === month ? ' selected' : '') + '>' + esc(label) + '</option>').join('')
    + '</select></label>'
    + '<div class="dse-grid">'
    + list.map((r) => '<label class="dse-field"><span>' + esc(r.drug_label) + '</span>'
      + '<input type="number" inputmode="numeric" min="0" max="' + MAX + '" step="1" placeholder="Not counted"'
      + ' data-code="' + esc(r.drug_code) + '" value="' + (r.in_stock == null ? '' : esc(r.in_stock)) + '"></label>').join('')
    + '</div>'
    + '<div class="dse-actions"><button type="submit" class="dse-save">Save stock</button>'
    + '<span class="dse-msg" aria-live="polite"></span></div>'
    + '<div class="dse-last">' + (last ? 'Last saved ' + esc(last.saved_on) + (last.saved_by ? ' by ' + esc(last.saved_by) : '') + '.' : 'Nothing saved for this month yet.') + '</div>'
    + '</form>';
  if (recent && recent.month === month && recent.note) { message(recent.note, recent.cls); }
};

const message = (text, cls) => {
  const m = root.querySelector('.dse-msg');
  if (m) { m.className = 'dse-msg ' + (cls || ''); m.textContent = text; }
};

// --- Saving: posted to h360-api, which takes identity from the Grafana session.
const H360_API = location.protocol + '//' + location.hostname + ':8090';
const save = async (entries) => {
  const body = JSON.stringify({ org_unit_id: orgId, month, entries });
  const res = await fetch(H360_API + '/write/drug-stock', {method:'POST', credentials:'include', headers:{'Content-Type':'application/json','X-H360-Request':'1'}, body});
  const saved = await res.json().catch(() => ({}));
  const err = res.ok && saved.ok !== false ? '' : (saved.message || res.statusText);
  if (err) { throw new Error(err); }
  return saved;
};

const refreshBoard = () => {
  const g = context.grafana || {};
  const shown = typeof g.replaceVariables === 'function' ? g.replaceVariables('${reporting_month}') : '';
  if (shown !== month && g.locationService && typeof g.locationService.partial === 'function') {
    g.locationService.partial({ 'var-reporting_month': month }, true);
  } else if (typeof g.refresh === 'function') {
    g.refresh();
  }
};

root.addEventListener('change', (e) => {
  if (e.target.classList.contains('dse-month')) { month = e.target.value; render(); }
});

root.addEventListener('input', (e) => {
  if (e.target.dataset.code) { e.target.classList.remove('bad'); message(''); }
});

root.addEventListener('submit', async (e) => {
  e.preventDefault();
  const inputs = Array.from(root.querySelectorAll('input[data-code]'));
  let bad = false;
  const entries = inputs.map((el) => {
    const raw = el.value.trim();
    // A number input reports '' for text it cannot parse; validity tells that apart from blank.
    const blank = raw === '' && !(el.validity && el.validity.badInput);
    const ok = blank || (/^\d+$/.test(raw) && Number(raw) <= MAX);
    el.classList.toggle('bad', !ok);
    if (!ok) { bad = true; }
    return { drug_code: el.dataset.code, stock: blank ? null : Number(raw) };
  });
  if (bad) { message('Use whole numbers from 0 to ' + fmt(MAX) + ', or leave blank.', 'err'); return; }

  const btn = root.querySelector('.dse-save');
  btn.disabled = true;
  message('Saving…');
  try {
    const saved = await save(entries);
    const kept = Number(saved.kept_newer || 0);
    const note = 'Saved ✓' + (kept ? ' A newer count is kept for ' + kept + (kept === 1 ? ' medicine.' : ' medicines.') : '');
    entries.forEach((en) => {
      const r = ofMonth(month).find((x) => x.drug_code === en.drug_code);
      if (r && !kept) { r.in_stock = en.stock; }
    });
    Object.assign(memo, { org: orgId, month, note, cls: 'ok', at: Date.now() });
    message(note, 'ok');
    refreshBoard();
  } catch (err) {
    message("Couldn't save. " + (err.message || 'Try again.'), 'err');
    if (context.grafana && context.grafana.notifyError) { context.grafana.notifyError(["Couldn't save stock", err.message]); }
  } finally {
    btn.disabled = false;
  }
});

render();

options.styles:
.dse { font-size: 13px; line-height: 1.35; }
.dse-title { font-size: 18px; font-weight: 700; margin: 0 0 4px; }
.dse-head { margin: 0 0 10px; }
.dse-note { font-size: 13px; color: #6E6E6E; padding: 4px 2px; }
.dse-form select, .dse-form input { font: inherit; color: #1c1c1c; background: #fff; border: 1px solid #d9e3ff; border-radius: 4px;
  padding: 4px 6px; height: 30px; line-height: 1.2; box-sizing: border-box; width: 100%; }
.dse-form input.bad { border-color: red; }
.dse-field { display: flex; flex-direction: column; gap: 3px; font-weight: 600; font-size: 12px; }
.dse-month-field { max-width: 200px; margin-bottom: 10px; }
.dse-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(170px, 1fr)); gap: 10px 14px; margin-bottom: 12px; }
.dse-actions { display: flex; align-items: center; gap: 12px; }
.dse-save { font: inherit; font-weight: 600; background: #0075eb; border: 1px solid #0075eb; color: #fff; border-radius: 4px; padding: 5px 14px; cursor: pointer; }
.dse-save:disabled { opacity: 0.6; cursor: default; }
.dse-msg { font-size: 12px; }
.dse-msg.ok { color: #3bb231; }
.dse-msg.err { color: red; }
.dse-last { font-size: 12px; color: #6E6E6E; margin-top: 8px; }
.dse-warn { color: #e02424; background: rgba(224,36,36,0.05); border-left: 4px solid #e02424; padding: 8px 14px; font-size: 13px; display: flex; align-items: center; gap: 8px; border-radius: 2px; line-height: 1.4; }
